use std::collections::HashMap;

pub fn compile_source(source: &str) -> Result<String, Error> {
    let mut parser = Parser::new(source);
    let items = parser.parse_program()?;
    let mut env = HashMap::new();
    compile_items(&items, &mut env).map_err(Error::Compile)
}

#[derive(Debug)]
pub enum Error {
    Parse(ParseError),
    Compile(CompileError),
}

impl Error {
    pub fn render(&self, source: &str) -> String {
        match self {
            Self::Parse(err) => err.render(source),
            Self::Compile(err) => format!("Error: {}", err.0),
        }
    }
}

#[derive(Debug)]
pub struct ParseError {
    pos: usize,
    message: &'static str,
}

impl ParseError {
    fn new(pos: usize, message: &'static str) -> Self {
        Self { pos, message }
    }

    fn render(&self, source: &str) -> String {
        let (line_number, column_number, line_text) = line_context(source, self.pos);
        let caret_padding = " ".repeat(column_number.saturating_sub(1));

        format!(
            "Error:  --> {line_number}:{column_number}\n  |\n{line_number} | {line_text}\n  | {caret_padding}^---\n  |\n  = {}",
            self.message
        )
    }
}

#[derive(Debug)]
pub struct CompileError(pub String);

#[derive(Clone, Debug)]
enum Expr {
    Literal(String),
    Raw(String),
    Symbol(String),
    Range { start: char, end: char },
    NotClass(ClassExpr),
    Quantified { quantity: Quantity, target: Box<Expr> },
    Group { kind: GroupKind, items: Vec<Expr> },
    Assertion { kind: AssertionKind, items: Vec<Expr> },
    VarDecl { name: String, items: Vec<Expr> },
    VarUse(String),
}

impl Expr {
    fn requires_terminator(&self) -> bool {
        match self {
            Self::Literal(_)
            | Self::Raw(_)
            | Self::Symbol(_)
            | Self::Range { .. }
            | Self::NotClass(_)
            | Self::VarUse(_) => true,
            Self::Quantified { target, .. } => target.requires_terminator(),
            Self::Group { .. } | Self::Assertion { .. } | Self::VarDecl { .. } => false,
        }
    }
}

#[derive(Clone, Debug)]
enum ClassExpr {
    Char(char),
    Symbol(String),
    Range { start: char, end: char },
}

#[derive(Clone, Debug)]
enum Quantity {
    Exact(String),
    Range(String, String),
    Some,
    Any,
    Option,
}

#[derive(Clone, Copy, Debug)]
enum GroupKind {
    Match,
    Capture,
    Either,
}

#[derive(Clone, Copy, Debug)]
enum AssertionKind {
    Ahead,
    NotAhead,
    Behind,
    NotBehind,
}

struct Parser<'a> {
    source: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(source: &'a str) -> Self {
        Self { source, pos: 0 }
    }

    fn parse_program(&mut self) -> Result<Vec<Expr>, Error> {
        self.parse_items(None).map_err(Error::Parse)
    }

    fn parse_items(&mut self, terminator: Option<char>) -> Result<Vec<Expr>, ParseError> {
        let mut items = Vec::new();
        self.skip_ws_and_comments();

        loop {
            self.skip_ws_and_comments();

            if let Some(terminator) = terminator {
                if self.peek_char() == Some(terminator) {
                    if items.is_empty() {
                        return Err(ParseError::new(
                            self.pos,
                            "expected literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                        ));
                    }
                    self.bump_char();
                    break;
                }
            } else if self.is_eof() {
                break;
            }

            if self.is_eof() {
                if terminator.is_some() {
                    return Err(ParseError::new(
                        self.pos,
                        "expected literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                    ));
                }
                break;
            }

            let item_start = self.pos;
            let expr = self.parse_expr(true)?;
            let needs_terminator = expr.requires_terminator();

            if needs_terminator {
                self.skip_ws_and_comments();
                if !self.consume_char(';') {
                    return Err(ParseError::new(item_start, "expected root"));
                }
            }

            items.push(expr);
            self.skip_ws_and_comments();

            if terminator.is_none() && self.is_eof() {
                break;
            }
        }

        Ok(items)
    }

    fn parse_expr(&mut self, allow_quantifier: bool) -> Result<Expr, ParseError> {
        self.skip_ws_and_comments();
        let start = self.pos;

        if self.consume_keyword("let") {
            return self.parse_var_decl();
        }

        if self.consume_keyword("match") {
            return self.parse_group(GroupKind::Match);
        }

        if self.consume_keyword("capture") {
            return self.parse_group(GroupKind::Capture);
        }

        if self.consume_keyword("either") {
            return self.parse_group(GroupKind::Either);
        }

        if self.consume_keyword("ahead") {
            return self.parse_assertion(AssertionKind::Ahead);
        }

        if self.consume_keyword("behind") {
            return self.parse_assertion(AssertionKind::Behind);
        }

        if self.consume_keyword("not") {
            return self.parse_not();
        }

        if allow_quantifier {
            if let Some(quantity) = self.try_parse_quantity()? {
                self.skip_ws_and_comments();
                if self.consume_keyword("of") {
                    let target_pos = self.pos;
                    let target = self.parse_expr(false).map_err(|_| {
                        ParseError::new(
                            target_pos,
                            "expected literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                        )
                    })?;
                    return Ok(Expr::Quantified {
                        quantity,
                        target: Box::new(target),
                    });
                }

                self.pos = start;
            }
        }

        match self.peek_char() {
            Some('"') | Some('\'') => self.parse_literal().map(Expr::Literal),
            Some('`') => self.parse_raw().map(Expr::Raw),
            Some('<') => self.parse_symbol().map(Expr::Symbol),
            Some('.') => self.parse_var_use(),
            Some(ch) if can_start_range_char(ch) => self.parse_range_root(),
            _ => Err(ParseError::new(start, "expected root")),
        }
    }

    fn parse_var_decl(&mut self) -> Result<Expr, ParseError> {
        self.skip_ws_and_comments();
        let name = self.parse_dotted_identifier()?;
        self.skip_ws_and_comments();

        if !self.consume_char('=') {
            return Err(ParseError::new(self.pos, "expected block"));
        }

        self.skip_ws_and_comments();
        if !self.consume_char('{') {
            return Err(ParseError::new(self.pos, "expected block"));
        }

        let items = self.parse_items(Some('}'))?;
        Ok(Expr::VarDecl { name, items })
    }

    fn parse_group(&mut self, kind: GroupKind) -> Result<Expr, ParseError> {
        self.skip_ws_and_comments();
        if !self.consume_char('{') {
            return Err(ParseError::new(
                self.pos,
                "expected literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
            ));
        }

        let items = self.parse_items(Some('}'))?;
        Ok(Expr::Group { kind, items })
    }

    fn parse_assertion(&mut self, kind: AssertionKind) -> Result<Expr, ParseError> {
        self.skip_ws_and_comments();
        if !self.consume_char('{') {
            return Err(ParseError::new(
                self.pos,
                "expected literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
            ));
        }

        let items = self.parse_items(Some('}'))?;
        Ok(Expr::Assertion { kind, items })
    }

    fn parse_not(&mut self) -> Result<Expr, ParseError> {
        self.skip_ws_and_comments();

        if self.consume_keyword("ahead") {
            return self.parse_assertion(AssertionKind::NotAhead);
        }

        if self.consume_keyword("behind") {
            return self.parse_assertion(AssertionKind::NotBehind);
        }

        let start = self.pos;
        let class = self.parse_class_expr().map_err(|_| {
            ParseError::new(start, "expected amount, class_content, or assertion_type")
        })?;
        Ok(Expr::NotClass(class))
    }

    fn parse_class_expr(&mut self) -> Result<ClassExpr, ParseError> {
        self.skip_ws_and_comments();
        let save = self.pos;

        if self.peek_char() == Some('<') {
            return self.parse_symbol().map(ClassExpr::Symbol);
        }

        let start = self.parse_class_char()?;
        let checkpoint = self.pos;
        self.skip_ws_and_comments();

        if self.consume_keyword("to") {
            self.skip_ws_and_comments();
            let end = self.parse_class_char()?;
            return Ok(ClassExpr::Range { start, end });
        }

        self.pos = checkpoint;
        if save == checkpoint {
            self.parse_class_char().map(ClassExpr::Char)
        } else {
            Ok(ClassExpr::Char(start))
        }
    }

    fn parse_range_root(&mut self) -> Result<Expr, ParseError> {
        let start_pos = self.pos;
        let start = self.parse_class_char().map_err(|_| ParseError::new(start_pos, "expected root"))?;
        self.skip_ws_and_comments();

        if !self.consume_keyword("to") {
            return Err(ParseError::new(start_pos, "expected root"));
        }

        self.skip_ws_and_comments();
        let end = self.parse_class_char().map_err(|_| ParseError::new(start_pos, "expected root"))?;
        Ok(Expr::Range { start, end })
    }

    fn parse_var_use(&mut self) -> Result<Expr, ParseError> {
        self.consume_char('.');
        let name = self.parse_identifier()?;
        Ok(Expr::VarUse(name))
    }

    fn parse_dotted_identifier(&mut self) -> Result<String, ParseError> {
        if !self.consume_char('.') {
            return Err(ParseError::new(self.pos, "expected identifier"));
        }

        self.parse_identifier()
    }

    fn parse_identifier(&mut self) -> Result<String, ParseError> {
        let start = self.pos;
        let Some(first) = self.peek_char() else {
            return Err(ParseError::new(self.pos, "expected identifier"));
        };

        if !first.is_ascii_alphabetic() {
            return Err(ParseError::new(self.pos, "expected identifier"));
        }

        let mut output = String::new();
        output.push(first);
        self.bump_char();

        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                output.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }

        if output.is_empty() {
            Err(ParseError::new(start, "expected identifier"))
        } else {
            Ok(output)
        }
    }

    fn parse_symbol(&mut self) -> Result<String, ParseError> {
        let start = self.pos;
        if !self.consume_char('<') {
            return Err(ParseError::new(start, "expected root"));
        }

        let mut name = String::new();
        while let Some(ch) = self.peek_char() {
            if ch == '>' {
                self.bump_char();
                return Ok(name);
            }
            if ch.is_ascii_alphabetic() {
                name.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }

        Err(ParseError::new(start, "expected root"))
    }

    fn parse_literal(&mut self) -> Result<String, ParseError> {
        let start = self.pos;
        let quote = self.bump_char().ok_or_else(|| ParseError::new(start, "expected root"))?;
        let mut output = String::new();

        while let Some(ch) = self.peek_char() {
            if ch == quote {
                self.bump_char();
                return Ok(output);
            }

            if ch == '\n' || ch == '\r' {
                return Err(ParseError::new(start, "expected root"));
            }

            if ch == '\\' {
                self.bump_char();
                let Some(escaped) = self.peek_char() else {
                    return Err(ParseError::new(start, "expected root"));
                };

                match escaped {
                    '\\' => output.push('\\'),
                    'n' => output.push('\n'),
                    'r' => output.push('\r'),
                    't' => output.push('\t'),
                    '"' => output.push('"'),
                    '\'' => output.push('\''),
                    _ => return Err(ParseError::new(start, "expected root")),
                }
                self.bump_char();
                continue;
            }

            output.push(ch);
            self.bump_char();
        }

        Err(ParseError::new(start, "expected root"))
    }

    fn parse_raw(&mut self) -> Result<String, ParseError> {
        let start = self.pos;
        if !self.consume_char('`') {
            return Err(ParseError::new(start, "expected root"));
        }

        let mut output = String::new();

        while let Some(ch) = self.peek_char() {
            match ch {
                '`' => {
                    self.bump_char();
                    return Ok(output);
                }
                '\\' => {
                    self.bump_char();
                    let Some(escaped) = self.peek_char() else {
                        return Err(ParseError::new(start, "expected root"));
                    };

                    match escaped {
                        '`' => {
                            output.push('`');
                            self.bump_char();
                        }
                        '\\' => {
                            output.push('\\');
                            output.push('\\');
                            self.bump_char();
                        }
                        _ => return Err(ParseError::new(start, "expected root")),
                    }
                }
                _ => {
                    output.push(ch);
                    self.bump_char();
                }
            }
        }

        Err(ParseError::new(start, "expected root"))
    }

    fn try_parse_quantity(&mut self) -> Result<Option<Quantity>, ParseError> {
        self.skip_ws_and_comments();
        let start = self.pos;

        if self.consume_keyword("some") {
            return Ok(Some(Quantity::Some));
        }
        if self.consume_keyword("any") {
            return Ok(Some(Quantity::Any));
        }
        if self.consume_keyword("option") {
            return Ok(Some(Quantity::Option));
        }

        let Some(ch) = self.peek_char() else {
            return Ok(None);
        };
        if !ch.is_ascii_digit() {
            return Ok(None);
        }

        let first = self.parse_number();
        self.skip_ws_and_comments();

        if self.consume_keyword("to") {
            self.skip_ws_and_comments();
            if self.peek_char().is_some_and(|ch| ch.is_ascii_digit()) {
                let second = self.parse_number();
                return Ok(Some(Quantity::Range(first, second)));
            }

            return Err(ParseError::new(start, "expected root"));
        }

        Ok(Some(Quantity::Exact(first)))
    }

    fn parse_number(&mut self) -> String {
        let mut output = String::new();
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_digit() {
                output.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }
        output
    }

    fn parse_class_char(&mut self) -> Result<char, ParseError> {
        self.skip_ws_and_comments();
        let Some(ch) = self.peek_char() else {
            return Err(ParseError::new(self.pos, "expected root"));
        };

        if ch == '\\' {
            self.bump_char();
            let Some(escaped) = self.peek_char() else {
                return Err(ParseError::new(self.pos, "expected root"));
            };

            match escaped {
                '\\' | '^' | '*' | '$' => {
                    self.bump_char();
                    return Ok(escaped);
                }
                _ => return Err(ParseError::new(self.pos, "expected root")),
            }
        }

        if ch.is_ascii_alphanumeric() || matches!(ch, '_' | '*' | '$' | '^') {
            self.bump_char();
            return Ok(ch);
        }

        Err(ParseError::new(self.pos, "expected root"))
    }

    fn skip_ws_and_comments(&mut self) {
        loop {
            let Some(ch) = self.peek_char() else {
                return;
            };

            if ch.is_whitespace() {
                self.bump_char();
                continue;
            }

            if self.source[self.pos..].starts_with("//") {
                while let Some(ch) = self.peek_char() {
                    self.bump_char();
                    if ch == '\n' {
                        break;
                    }
                }
                continue;
            }

            if self.source[self.pos..].starts_with("/*") {
                self.pos += 2;
                while self.pos < self.source.len() && !self.source[self.pos..].starts_with("*/") {
                    self.bump_char();
                }
                if self.source[self.pos..].starts_with("*/") {
                    self.pos += 2;
                }
                continue;
            }

            return;
        }
    }

    fn consume_keyword(&mut self, keyword: &str) -> bool {
        if !self.source[self.pos..].starts_with(keyword) {
            return false;
        }

        let after = self.pos + keyword.len();
        if let Some(next) = self.source[after..].chars().next() {
            if next.is_ascii_alphabetic() || next == '_' {
                return false;
            }
        }

        self.pos = after;
        true
    }

    fn consume_char(&mut self, expected: char) -> bool {
        match self.peek_char() {
            Some(ch) if ch == expected => {
                self.bump_char();
                true
            }
            _ => false,
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.source[self.pos..].chars().next()
    }

    fn bump_char(&mut self) -> Option<char> {
        let ch = self.peek_char()?;
        self.pos += ch.len_utf8();
        Some(ch)
    }

    fn is_eof(&self) -> bool {
        self.pos >= self.source.len()
    }
}

fn compile_items(items: &[Expr], env: &mut HashMap<String, String>) -> Result<String, CompileError> {
    let mut output = String::new();
    for item in items {
        output.push_str(&compile_expr(item, env)?);
    }
    Ok(output)
}

fn compile_expr(expr: &Expr, env: &mut HashMap<String, String>) -> Result<String, CompileError> {
    match expr {
        Expr::Literal(value) => Ok(escape_literal(value)),
        Expr::Raw(value) => Ok(value.clone()),
        Expr::Symbol(name) => compile_symbol(name, false),
        Expr::Range { start, end } => Ok(format!("[{start}-{end}]")),
        Expr::NotClass(class) => compile_not_class(class),
        Expr::Quantified { quantity, target } => compile_quantified(quantity, target, env),
        Expr::Group { kind, items } => {
            let inner = compile_items(items, env)?;
            match kind {
                GroupKind::Match => Ok(format!("(?:{inner})")),
                GroupKind::Capture => Ok(format!("({inner})")),
                GroupKind::Either => {
                    let parts = compile_either_items(items, env)?;
                    Ok(format!("(?:{})", parts.join("|")))
                }
            }
        }
        Expr::Assertion { kind, items } => {
            let inner = compile_items(items, env)?;
            match kind {
                AssertionKind::Ahead => Ok(format!("(?={inner})")),
                AssertionKind::NotAhead => Ok(format!("(?!{inner})")),
                AssertionKind::Behind => Ok(format!("(?<={inner})")),
                AssertionKind::NotBehind => Ok(format!("(?<!{inner})")),
            }
        }
        Expr::VarDecl { name, items } => {
            let compiled = compile_items(items, env)?;
            env.insert(name.clone(), compiled);
            Ok(String::new())
        }
        Expr::VarUse(name) => env
            .get(name)
            .cloned()
            .ok_or_else(|| CompileError("usage of an uninitialized variable".to_string())),
    }
}

fn compile_either_items(items: &[Expr], env: &mut HashMap<String, String>) -> Result<Vec<String>, CompileError> {
    let mut compiled = Vec::with_capacity(items.len());
    for item in items {
        compiled.push(compile_expr(item, env)?);
    }
    Ok(compiled)
}

fn compile_quantified(quantity: &Quantity, target: &Expr, env: &mut HashMap<String, String>) -> Result<String, CompileError> {
    if matches!(target, Expr::Assertion { .. }) {
        return Err(CompileError("unexpected assertion in quantifier".to_string()));
    }

    if matches!(target, Expr::VarUse(_)) {
        return Err(CompileError("unexpected variable invocation in quantifier".to_string()));
    }

    if matches!(target, Expr::VarDecl { .. }) {
        return Err(CompileError("unexpected variable declaration in quantifier".to_string()));
    }

    if let Expr::Symbol(name) = target {
        let compiled = compile_symbol(name, false)?;
        if matches!(name.as_str(), "start" | "end") {
            return Err(CompileError("unexpected special symbol in quantifier".to_string()));
        }
        return Ok(apply_quantity(&compiled, quantity, false));
    }

    let compiled = compile_expr(target, env)?;
    let wrap = quantifier_needs_group(target, &compiled);
    Ok(apply_quantity(&compiled, quantity, wrap))
}

fn apply_quantity(target: &str, quantity: &Quantity, wrap: bool) -> String {
    let base = if wrap {
        format!("(?:{target})")
    } else {
        target.to_string()
    };

    match quantity {
        Quantity::Exact(amount) => format!("{base}{{{amount}}}"),
        Quantity::Range(min, max) => format!("{base}{{{min},{max}}}"),
        Quantity::Some => format!("{base}+"),
        Quantity::Any => format!("{base}*"),
        Quantity::Option => format!("{base}?"),
    }
}

fn quantifier_needs_group(target: &Expr, compiled: &str) -> bool {
    match target {
        Expr::Literal(value) => value.chars().count() != 1,
        Expr::Raw(_) => !raw_is_single_atom(compiled),
        Expr::Group { .. } => false,
        Expr::Range { .. } => false,
        Expr::NotClass(_) => false,
        Expr::Symbol(_) => false,
        Expr::Assertion { .. } | Expr::VarDecl { .. } | Expr::VarUse(_) => false,
        Expr::Quantified { .. } => true,
    }
}

fn raw_is_single_atom(pattern: &str) -> bool {
    if pattern.is_empty() {
        return false;
    }

    parse_single_atom(pattern).is_some_and(|len| len == pattern.len())
}

fn parse_single_atom(pattern: &str) -> Option<usize> {
    let mut chars = pattern.char_indices();
    let (_, first) = chars.next()?;

    match first {
        '\\' => {
            let (offset, second) = chars.next()?;
            Some(offset + second.len_utf8())
        }
        '[' => scan_character_class(pattern),
        '(' => scan_group(pattern),
        _ => Some(first.len_utf8()),
    }
}

fn scan_character_class(pattern: &str) -> Option<usize> {
    let mut escaped = false;
    for (offset, ch) in pattern.char_indices().skip(1) {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        if ch == ']' {
            return Some(offset + ch.len_utf8());
        }
    }
    None
}

fn scan_group(pattern: &str) -> Option<usize> {
    let mut depth = 0usize;
    let mut in_class = false;
    let mut escaped = false;

    for (offset, ch) in pattern.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }

        if ch == '\\' {
            escaped = true;
            continue;
        }

        if in_class {
            if ch == ']' {
                in_class = false;
            }
            continue;
        }

        match ch {
            '[' => in_class = true,
            '(' => depth += 1,
            ')' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(offset + ch.len_utf8());
                }
            }
            _ => {}
        }
    }

    None
}

fn compile_symbol(name: &str, negated: bool) -> Result<String, CompileError> {
    match (name, negated) {
        ("char", false) => Ok(".".to_string()),
        ("char", true) => Err(CompileError("negative char not allowed".to_string())),
        ("space", false) => Ok(" ".to_string()),
        ("space", true) => Ok("[^ ]".to_string()),
        ("whitespace", false) => Ok("\\s".to_string()),
        ("whitespace", true) => Ok("\\S".to_string()),
        ("digit", false) => Ok("\\d".to_string()),
        ("digit", true) => Ok("\\D".to_string()),
        ("word", false) => Ok("\\w".to_string()),
        ("word", true) => Ok("\\W".to_string()),
        ("tab", false) => Ok("\\t".to_string()),
        ("tab", true) => Ok("[^\\t]".to_string()),
        ("newline", false) => Ok("\\n".to_string()),
        ("newline", true) => Ok("[^\\n]".to_string()),
        ("return", false) => Ok("\\r".to_string()),
        ("return", true) => Ok("[^\\r]".to_string()),
        ("start", false) => Ok("^".to_string()),
        ("start", true) => Err(CompileError("negative start not allowed".to_string())),
        ("end", false) => Ok("$".to_string()),
        ("end", true) => Err(CompileError("negative end not allowed".to_string())),
        ("boundary", false) => Ok("\\b".to_string()),
        ("boundary", true) => Ok("\\B".to_string()),
        _ => Err(CompileError("usage of an unrecognized symbol".to_string())),
    }
}

fn compile_not_class(class: &ClassExpr) -> Result<String, CompileError> {
    match class {
        ClassExpr::Char(ch) => Ok(format!("[^{ch}]")),
        ClassExpr::Symbol(name) => compile_symbol(name, true),
        ClassExpr::Range { start, end } => Ok(format!("[^{start}-{end}]")),
    }
}

fn escape_literal(value: &str) -> String {
    let mut escaped = String::new();

    for ch in value.chars() {
        match ch {
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            '.' | '^' | '$' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '\\'
            | '|' => {
                escaped.push('\\');
                escaped.push(ch);
            }
            _ => escaped.push(ch),
        }
    }

    escaped
}

fn can_start_range_char(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || matches!(ch, '_' | '*' | '$' | '^')
}

fn line_context(source: &str, pos: usize) -> (usize, usize, String) {
    let mut line_number = 1usize;
    let mut line_start = 0usize;

    for (offset, ch) in source.char_indices() {
        if offset >= pos {
            break;
        }

        if ch == '\n' {
            line_number += 1;
            line_start = offset + 1;
        }
    }

    let line_end = source[line_start..]
        .find('\n')
        .map(|offset| line_start + offset)
        .unwrap_or(source.len());
    let line_text = source[line_start..line_end].to_string();

    let column_number = source[line_start..pos.min(source.len())].chars().count() + 1;

    (line_number, column_number, line_text)
}

