    }

    #[test]
    fn compiles_groups_and_alternation() {
        let source = "2 of either { \"a\"; match { \"b\"; \"c\"; } }";
        assert_eq!(compile_source(source).unwrap(), "(?:a|(?:bc)){2}");
    }

    #[test]
    fn compiles_variables_in_source_order() {
        let source = "either { let .Foo = { \"a\"; } .Foo; } .Foo;";
        assert_eq!(compile_source(source).unwrap(), "(?:|a)a");
    }

    #[test]
    fn compiles_ranges_and_negation() {
        let source = "some of not a to z;";
        assert_eq!(compile_source(source).unwrap(), "[^a-z]+");
    }

    #[test]
    fn ignores_comments() {
        let source = "// comment\n/* block */\n\"a\";\n";
        assert_eq!(compile_source(source).unwrap(), "a");
    }
}

