mod melody;

use clap::{Arg, ArgAction, Command};
use clap_complete::{generate, Shell};
use std::fs;
use std::io::{self, IsTerminal, Write};
use std::process;

const EX_USAGE: i32 = 64;
const EX_DATAERR: i32 = 65;
const EX_NOINPUT: i32 = 66;
const EX_IOERR: i32 = 74;

fn main() {
    process::exit(run());
}

fn run() -> i32 {
    let matches = match build_cli("melody_cli", "executable").try_get_matches() {
        Ok(matches) => matches,
        Err(err) => {
            let _ = err.print();
            return err.exit_code();
        }
    };

    if matches.get_flag("repl") {
        if !io::stdin().is_terminal() || !io::stdout().is_terminal() {
            eprintln!("Error: repl argument supplied with piped input or output");
            return EX_USAGE;
        }

        return run_repl();
    }

    if let Some(shell_name) = matches.get_one::<String>("generate-completions") {
        output_completions(shell_name);
        return 0;
    }

    let source = match read_source(matches.get_one::<String>("input-file-path").map(String::as_str)) {
        Ok(source) => source,
        Err(SourceError::NoInput) => {
            print_no_input_message();
            return EX_NOINPUT;
        }
        Err(SourceError::ReadInput(path)) => {
            eprintln!("Error: unable read file at path {}", path);
            return EX_DATAERR;
        }
        Err(SourceError::ReadStdin) => {
            eprintln!("Error: unable read file at path -");
            return EX_DATAERR;
        }
    };

    let regex = match melody::compile_source(&source) {
        Ok(regex) => regex,
        Err(err) => {
            eprintln!("{}", err.render(&source));
            return EX_DATAERR;
        }
    };

    if let Some(output_path) = matches.get_one::<String>("output") {
        if fs::write(output_path, regex.as_bytes()).is_err() {
            eprintln!("Error: {}", output_path);
            return EX_IOERR;
        }

        return 0;
    }

    if let Some(test_file) = matches.get_one::<String>("test-file") {
        let contents = match fs::read_to_string(test_file) {
            Ok(contents) => contents,
            Err(_) => {
                eprintln!("Error: unable read file at path {}", test_file);
                return EX_IOERR;
            }
        };

        let regex = match compile_runtime_regex(&regex) {
            Ok(regex) => regex,
            Err(message) => {
                eprintln!("{}", message);
                return EX_DATAERR;
            }
        };

        let matched = match regex.is_match(&contents) {
            Ok(matched) => matched,
            Err(err) => {
                eprintln!("Error: {}", err);
                return EX_DATAERR;
            }
        };

        if matched {
            println!("{test_file} matched");
        } else {
            println!("{test_file} did not match");
        }

        return 0;
    }

    if let Some(test) = matches.get_one::<String>("test") {
        let regex = match compile_runtime_regex(&regex) {
            Ok(regex) => regex,
            Err(message) => {
                eprintln!("{}", message);
                return EX_DATAERR;
            }
        };

        let matched = match regex.is_match(test) {
            Ok(matched) => matched,
            Err(err) => {
                eprintln!("Error: {}", err);
                return EX_DATAERR;
            }
        };

        if matched {
            println!("'{test}' matched");
        } else {
            println!("'{test}' did not match");
        }

        return 0;
    }

    println!("{regex}");
    0
}

fn build_cli(display_name: &'static str, bin_name: &'static str) -> Command {
    Command::new(display_name)
        .bin_name(bin_name)
        .about("A CLI wrapping the Melody language compiler")
        .disable_help_subcommand(true)
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("OUTPUT_FILE_PATH")
                .help("Write to a file")
                .conflicts_with_all(["generate-completions", "test", "test-file"]),
        )
        .arg(
            Arg::new("no-color")
                .short('n')
                .long("no-color")
                .action(ArgAction::SetTrue)
                .help("Print output with no color"),
        )
        .arg(
            Arg::new("repl")
                .short('r')
                .long("repl")
                .action(ArgAction::SetTrue)
                .help("Start the Melody REPL")
                .conflicts_with_all(["generate-completions", "test", "test-file"]),
        )
        .arg(
            Arg::new("generate-completions")
                .long("generate-completions")
                .value_name("completions")
                .help(
                    "Outputs completions for the selected shell\nTo use, write the output to the appropriate location for your shell",
                )
                .conflicts_with_all(["output", "repl", "test", "test-file", "input-file-path"]),
        )
        .arg(
            Arg::new("test")
                .short('t')
                .long("test")
                .value_name("test")
                .help("Test the compiled regex against a string")
                .conflicts_with_all(["output", "repl", "generate-completions", "test-file"]),
        )
        .arg(
            Arg::new("test-file")
                .short('f')
                .long("test-file")
                .value_name("test-file")
                .help("Test the compiled regex against the contents of a file")
                .conflicts_with_all(["output", "repl", "generate-completions", "test"]),
        )
        .arg(
            Arg::new("input-file-path")
                .value_name("INPUT_FILE_PATH")
                .help("Read from a file\nUse '-' and or pipe input to read from stdin"),
        )
        .version("0.20.0")
}

enum SourceError {
    NoInput,
    ReadInput(String),
    ReadStdin,
}

fn read_source(input_path: Option<&str>) -> Result<String, SourceError> {
    if let Some(input_path) = input_path {
        if input_path == "-" {
            return io::read_to_string(io::stdin()).map_err(|_| SourceError::ReadStdin);
        }

        return fs::read_to_string(input_path).map_err(|_| SourceError::ReadInput(input_path.to_string()));
    }

    if io::stdin().is_terminal() {
        return Err(SourceError::NoInput);
    }

    io::read_to_string(io::stdin()).map_err(|_| SourceError::ReadStdin)
}

fn output_completions(shell_name: &str) {
    let mut command = build_cli("melody", "melody");
    let mut stdout = io::stdout();

    match shell_name {
        "bash" => generate(Shell::Bash, &mut command, "melody", &mut stdout),
        "zsh" => generate(Shell::Zsh, &mut command, "melody", &mut stdout),
        "fish" => generate(Shell::Fish, &mut command, "melody", &mut stdout),
        "elvish" => generate(Shell::Elvish, &mut command, "melody", &mut stdout),
        "powershell" => generate(Shell::PowerShell, &mut command, "melody", &mut stdout),
        _ => {
            println!("Unknown or unsupported shell: '{shell_name}'");
            println!("Try one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'");
        }
    }
}

fn compile_runtime_regex(pattern: &str) -> Result<fancy_regex::Regex, String> {
    fancy_regex::Regex::new(pattern).map_err(|err| {
        format!(
            "Error: could not compile regex\nCause: {}\nRegex: {}",
            err, pattern
        )
    })
}

fn print_no_input_message() {
    println!("No input file supplied and no input piped");
    println!("Try adding a path argument: 'melody ./file.mdy'");
    println!();

    let mut command = build_cli("melody_cli", "melody_cli");
    let _ = command.print_help();
    println!();
}

fn run_repl() -> i32 {
    println!("Melody REPL v0.20.0");
    println!();
    println!("Commands:");
    println!();
    println!("- :u, :undo - undo the latest line");
    println!("- :r, :redo - redo the latest undo");
    println!("- :c, :clear - clear all REPL history and previous input");
    println!("- :s, :source - print all previously entered lines");
    println!("- :e, :exit - exit the REPL");
    println!();

    let stdin = io::stdin();
    let mut history: Vec<String> = Vec::new();
    let mut redo: Vec<String> = Vec::new();

    loop {
        print!("~ ");
        let _ = io::stdout().flush();

        let mut line = String::new();
        let read = match stdin.read_line(&mut line) {
            Ok(read) => read,
            Err(_) => return 0,
        };

        if read == 0 {
            return 0;
        }

        while matches!(line.chars().last(), Some('\n' | '\r')) {
            line.pop();
        }

        match line.as_str() {
            ":u" | ":undo" => {
                if let Some(last) = history.pop() {
                    redo.push(last);
                    println!("undo");
                } else {
                    println!("nothing to undo");
                }
                println!();
            }
            ":r" | ":redo" => {
                if let Some(last) = redo.pop() {
                    history.push(last);
                    println!("redo");
                    match melody::compile_source(&history.join("\n")) {
                        Ok(regex) => println!("{regex}"),
                        Err(err) => println!("{}", err.render(&history.join("\n"))),
                    }
                } else {
                    println!("nothing to redo");
                }
                println!();
            }
            ":c" | ":clear" => {
                history.clear();
                redo.clear();
                println!("clear");
                println!();
            }
            ":s" | ":source" => {
                if history.is_empty() {
                    println!("no lines to print");
                } else {
                    println!("source");
                    for (index, item) in history.iter().enumerate() {
                        println!("{} {}", index + 1, item);
                    }
                }
                println!();
            }
            ":e" | ":exit" => {
                println!("exit");
                return 0;
            }
            command if command.starts_with(':') => {
                println!("Error: unrecognized command \"{command}\"");
                println!();
            }
            _ => {
                redo.clear();
                history.push(line);
                let source = history.join("\n");
                match melody::compile_source(&source) {
                    Ok(regex) => println!("{regex}"),
                    Err(err) => {
                        history.pop();
                        println!("{}", err.render(&source));
                    }
                }
                println!();
            }
        }
    }
}

