+                        match ch {
+                            'o' => {
+                                seen.check_duplicate(ArgId::Output)?;
+                                seen.check_conflict(
+                                    ArgId::Output,
+                                    &[ArgId::GenerateCompletions, ArgId::Test, ArgId::TestFile],
+                                )?;
+                                seen.mark(ArgId::Output);
+                                options.output = Some(value);
+                            }
+                            't' => {
+                                seen.check_duplicate(ArgId::Test)?;
+                                seen.check_conflict(
+                                    ArgId::Test,
+                                    &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::TestFile],
+                                )?;
+                                seen.mark(ArgId::Test);
+                                options.test = Some(value);
+                            }
+                            'f' => {
+                                seen.check_duplicate(ArgId::TestFile)?;
+                                seen.check_conflict(
+                                    ArgId::TestFile,
+                                    &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::Test],
+                                )?;
+                                seen.mark(ArgId::TestFile);
+                                options.test_file = Some(value);
+                            }
+                            _ => {}
+                        }
