use std::ffi::c_void;
use std::ptr::NonNull;

const PCRE2_ERROR_NOMATCH: i32 = -1;

pub struct Regex {
    code: NonNull<Pcre2Code>,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Self, String> {
        let mut error_code = 0i32;
        let mut error_offset = 0usize;
        let code = unsafe {
            pcre2_compile_8(
                pattern.as_ptr(),
                pattern.len(),
                0,
                &mut error_code,
                &mut error_offset,
                std::ptr::null_mut(),
            )
        };

        let code = NonNull::new(code).ok_or_else(|| error_message(error_code))?;
        let _ = error_offset;
        Ok(Self { code })
    }

    pub fn is_match(&self, subject: &str) -> Result<bool, String> {
        let match_data = NonNull::new(unsafe {
            pcre2_match_data_create_from_pattern_8(self.code.as_ptr(), std::ptr::null_mut())
        })
        .ok_or_else(|| "could not allocate match data".to_string())?;

        let rc = unsafe {
            pcre2_match_8(
                self.code.as_ptr(),
                subject.as_ptr(),
                subject.len(),
                0,
                0,
                match_data.as_ptr(),
                std::ptr::null_mut(),
            )
        };

        unsafe {
            pcre2_match_data_free_8(match_data.as_ptr());
        }

        if rc == PCRE2_ERROR_NOMATCH {
            return Ok(false);
        }

        if rc < 0 {
            return Err(error_message(rc));
        }

        Ok(true)
    }
}

impl Drop for Regex {
    fn drop(&mut self) {
        unsafe {
            pcre2_code_free_8(self.code.as_ptr());
        }
    }
}

fn error_message(code: i32) -> String {
    let mut buffer = vec![0u8; 256];
    let written = unsafe { pcre2_get_error_message_8(code, buffer.as_mut_ptr(), buffer.len()) };

    if written < 0 {
        return format!("PCRE2 error {}", code);
    }

    String::from_utf8_lossy(&buffer[..written as usize]).into_owned()
}

#[repr(C)]
struct Pcre2Code {
    _unused: [u8; 0],
}

#[repr(C)]
struct Pcre2MatchData {
    _unused: [u8; 0],
}

unsafe extern "C" {
    fn pcre2_compile_8(
        pattern: *const u8,
        length: usize,
        options: u32,
        error_code: *mut i32,
        error_offset: *mut usize,
        context: *mut c_void,
    ) -> *mut Pcre2Code;

    fn pcre2_code_free_8(code: *mut Pcre2Code);

    fn pcre2_match_data_create_from_pattern_8(
        code: *const Pcre2Code,
        context: *mut c_void,
    ) -> *mut Pcre2MatchData;

    fn pcre2_match_data_free_8(match_data: *mut Pcre2MatchData);

    fn pcre2_match_8(
        code: *const Pcre2Code,
        subject: *const u8,
        length: usize,
        start_offset: usize,
        options: u32,
        match_data: *mut Pcre2MatchData,
        context: *mut c_void,
    ) -> i32;

    fn pcre2_get_error_message_8(error_code: i32, buffer: *mut u8, buffer_len: usize) -> i32;
}

