mod completions;
mod melody;
mod pcre2;

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, IsTerminal, Write};
use std::process;

const EX_USAGE: i32 = 64;
const EX_DATAERR: i32 = 65;
const EX_NOINPUT: i32 = 66;
const EX_IOERR: i32 = 74;

const HELP_TEXT: &str = "\
A CLI wrapping the Melody language compiler

Usage: executable [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
";

const NO_INPUT_HELP_TEXT: &str = "\
A CLI wrapping the Melody language compiler

Usage: melody_cli [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
";

fn main() {
    process::exit(run());
}

fn run() -> i32 {
    let args = env::args().skip(1).collect::<Vec<_>>();

    let options = match parse_cli(&args) {
        Ok(CliOutcome::Help) => {
            print!("{HELP_TEXT}");
            return 0;
        }
        Ok(CliOutcome::Version) => {
            println!("melody_cli 0.20.0");
            return 0;
        }
        Ok(CliOutcome::Run(options)) => options,
        Err(err) => {
            eprint!("{}", err.render());
            return 2;
        }
    };

    if let Some(shell) = options.generate_completions.as_deref() {
        completions::print(shell);
        return 0;
    }

    if options.repl {
        if !io::stdin().is_terminal() || !io::stdout().is_terminal() {
            eprintln!("Error: repl argument supplied with piped input or output");
            return EX_USAGE;
        }

        return run_repl();
    }

    let source = match read_source(options.input_file_path.as_deref()) {
        Ok(source) => source,
        Err(SourceError::NoInput) => {
            print_no_input_message();
            return EX_NOINPUT;
        }
        Err(SourceError::ReadInput(path)) => {
            eprintln!("Error: unable read file at path {}", path);
            return EX_DATAERR;
        }
        Err(SourceError::ReadStdin) => {
            eprintln!("Error: unable read file at path -");
            return EX_DATAERR;
        }
    };

    let regex = match melody::compile_source(&source) {
        Ok(regex) => regex,
        Err(err) => {
            eprintln!("{}", err.render(&source));
            return EX_DATAERR;
        }
    };

    if let Some(output_path) = options.output.as_deref() {
        if fs::write(output_path, regex.as_bytes()).is_err() {
            eprintln!("Error: {}", output_path);
            return EX_IOERR;
        }

        return 0;
    }

    if let Some(test_file) = options.test_file.as_deref() {
        let contents = match fs::read_to_string(test_file) {
            Ok(contents) => contents,
            Err(_) => {
                eprintln!("Error: unable read file at path {}", test_file);
                return EX_IOERR;
            }
        };

        let regex = match compile_runtime_regex(&regex) {
            Ok(regex) => regex,
            Err(message) => {
                eprintln!("{}", message);
                return EX_DATAERR;
            }
        };

        match regex.is_match(&contents) {
            Ok(true) => println!("{test_file} matched"),
            Ok(false) => println!("{test_file} did not match"),
            Err(message) => {
                eprintln!("Error: {}", message);
                return EX_DATAERR;
            }
        }

        return 0;
    }

    if let Some(test) = options.test.as_deref() {
        let regex = match compile_runtime_regex(&regex) {
            Ok(regex) => regex,
            Err(message) => {
                eprintln!("{}", message);
                return EX_DATAERR;
            }
        };

        match regex.is_match(test) {
            Ok(true) => println!("'{test}' matched"),
            Ok(false) => println!("'{test}' did not match"),
            Err(message) => {
                eprintln!("Error: {}", message);
                return EX_DATAERR;
            }
        }

        return 0;
    }

    println!("{regex}");
    0
}

fn run_repl() -> i32 {
    println!("Melody REPL v0.20.0");
    println!();
    println!("Commands:");
    println!();
    println!("- :u, :undo - undo the latest line");
    println!("- :r, :redo - redo the latest undo");
    println!("- :c, :clear - clear all REPL history and previous input");
    println!("- :s, :source - print all previously entered lines");
    println!("- :e, :exit - exit the REPL");
    println!();

    let stdin = io::stdin();
    let mut history = Vec::<String>::new();
    let mut redo = Vec::<String>::new();

    loop {
        print!("~ ");
        let _ = io::stdout().flush();

        let mut line = String::new();
        let read = match stdin.read_line(&mut line) {
            Ok(read) => read,
            Err(_) => return 0,
        };

        if read == 0 {
            return 0;
        }

        while matches!(line.chars().last(), Some('\n' | '\r')) {
            line.pop();
        }

        match line.as_str() {
            ":u" | ":undo" => {
                if let Some(last) = history.pop() {
                    redo.push(last);
                    println!("undo");
                } else {
                    println!("nothing to undo");
                }
                println!();
            }
            ":r" | ":redo" => {
                if let Some(last) = redo.pop() {
                    history.push(last);
                    println!("redo");
                    let source = history.join("\n");
                    match melody::compile_source(&source) {
                        Ok(regex) => println!("{regex}"),
                        Err(err) => println!("{}", err.render(&source)),
                    }
                } else {
                    println!("nothing to redo");
                }
                println!();
            }
            ":c" | ":clear" => {
                history.clear();
                redo.clear();
                println!("clear");
                println!();
            }
            ":s" | ":source" => {
                if history.is_empty() {
                    println!("no lines to print");
                } else {
                    println!("source");
                    for (index, item) in history.iter().enumerate() {
                        println!("{} {}", index + 1, item);
                    }
                }
                println!();
            }
            ":e" | ":exit" => {
                println!("exit");
                return 0;
            }
            command if command.starts_with(':') => {
                println!("Error: unrecognized command \"{command}\"");
                println!();
            }
            _ => {
                redo.clear();
                history.push(line);
                let source = history.join("\n");
                match melody::compile_source(&source) {
                    Ok(regex) => println!("{regex}"),
                    Err(err) => {
                        history.pop();
                        println!("{}", err.render(&source));
                    }
                }
                println!();
            }
        }
    }
}

fn compile_runtime_regex(pattern: &str) -> Result<pcre2::Regex, String> {
    pcre2::Regex::new(pattern).map_err(|cause| {
        format!(
            "Error: could not compile regex\nCause: {}\nRegex: {}",
            cause, pattern
        )
    })
}

enum SourceError {
    NoInput,
    ReadInput(String),
    ReadStdin,
}

fn read_source(input_path: Option<&str>) -> Result<String, SourceError> {
    if let Some(input_path) = input_path {
        if input_path == "-" {
            return io::read_to_string(io::stdin()).map_err(|_| SourceError::ReadStdin);
        }

        return fs::read_to_string(input_path).map_err(|_| SourceError::ReadInput(input_path.to_string()));
    }

    if io::stdin().is_terminal() {
        return Err(SourceError::NoInput);
    }

    io::read_to_string(io::stdin()).map_err(|_| SourceError::ReadStdin)
}

fn print_no_input_message() {
    println!("No input file supplied and no input piped");
    println!("Try adding a path argument: 'melody ./file.mdy'");
    println!();
    print!("{NO_INPUT_HELP_TEXT}");
}

#[derive(Default)]
struct CliOptions {
    output: Option<String>,
    no_color: bool,
    repl: bool,
    generate_completions: Option<String>,
    test: Option<String>,
    test_file: Option<String>,
    input_file_path: Option<String>,
}

enum CliOutcome {
    Help,
    Version,
    Run(CliOptions),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum ArgId {
    Output,
    NoColor,
    Repl,
    GenerateCompletions,
    Test,
    TestFile,
    Input,
}

impl ArgId {
    fn display(self) -> &'static str {
        match self {
            Self::Output => "--output <OUTPUT_FILE_PATH>",
            Self::NoColor => "--no-color",
            Self::Repl => "--repl",
            Self::GenerateCompletions => "--generate-completions <completions>",
            Self::Test => "--test <test>",
            Self::TestFile => "--test-file <test-file>",
            Self::Input => "[INPUT_FILE_PATH]",
        }
    }

    fn conflict_usage(self, other: Self) -> &'static str {
        match self {
            Self::Output => match other {
                Self::Test | Self::TestFile => {
                    "Usage: executable --output <OUTPUT_FILE_PATH> <INPUT_FILE_PATH>\n\nFor more information, try '--help'.\n"
                }
                _ => {
                    "Usage: executable --output <OUTPUT_FILE_PATH> [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n"
                }
            },
            Self::Test => {
                "Usage: executable --test <test> <INPUT_FILE_PATH>\n\nFor more information, try '--help'.\n"
            }
            Self::TestFile => {
                "Usage: executable --test-file <test-file> <INPUT_FILE_PATH>\n\nFor more information, try '--help'.\n"
            }
            Self::Repl => {
                "Usage: executable --repl [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n"
            }
            Self::GenerateCompletions => {
                "Usage: executable --generate-completions <completions> [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n"
            }
            Self::NoColor | Self::Input => {
                "Usage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n"
            }
        }
    }
}

struct SeenArgs {
    seen: HashMap<ArgId, usize>,
    next_order: usize,
}

impl SeenArgs {
    fn new() -> Self {
        Self {
            seen: HashMap::new(),
            next_order: 0,
        }
    }

    fn check_duplicate(&self, id: ArgId) -> Result<(), CliError> {
        if self.seen.contains_key(&id) {
            return Err(CliError::Duplicate(id));
        }
        Ok(())
    }

    fn check_conflict(&self, new_id: ArgId, conflicts: &[ArgId]) -> Result<(), CliError> {
        let first = conflicts
            .iter()
            .filter_map(|id| self.seen.get(id).map(|order| (*id, *order)))
            .min_by_key(|(_, order)| *order)
            .map(|(id, _)| id);

        if let Some(first) = first {
            return Err(CliError::Conflict {
                first,
                second: new_id,
            });
        }

        Ok(())
    }

    fn mark(&mut self, id: ArgId) {
        self.next_order += 1;
        self.seen.insert(id, self.next_order);
    }
}

enum CliError {
    UnexpectedArgument { arg: String, tip: bool },
    MissingValue(&'static str),
    Duplicate(ArgId),
    Conflict { first: ArgId, second: ArgId },
}

impl CliError {
    fn render(&self) -> String {
        match self {
            Self::UnexpectedArgument { arg, tip } => {
                let mut output = format!("error: unexpected argument '{}' found\n\n", arg);
                if *tip {
                    output.push_str(&format!(
                        "  tip: to pass '{}' as a value, use '-- {}'\n\n",
                        arg, arg
                    ));
                }
                output.push_str("Usage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n");
                output
            }
            Self::MissingValue(arg) => {
                format!(
                    "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
                    arg
                )
            }
            Self::Duplicate(id) => {
                format!(
                    "error: the argument '{}' cannot be used multiple times\n\nUsage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n",
                    id.display()
                )
            }
            Self::Conflict { first, second } => {
                format!(
                    "error: the argument '{}' cannot be used with '{}'\n\n{}",
                    first.display(),
                    second.display(),
                    first.conflict_usage(*second)
                )
            }
        }
    }
}

fn parse_cli(args: &[String]) -> Result<CliOutcome, CliError> {
    let mut options = CliOptions::default();
    let mut seen = SeenArgs::new();
    let mut stop_parsing_options = false;
    let mut index = 0usize;

    while index < args.len() {
        let arg = &args[index];

        if stop_parsing_options {
            set_input_path(&mut options, &mut seen, arg.clone())?;
            index += 1;
            continue;
        }

        if arg == "--" {
            stop_parsing_options = true;
            index += 1;
            continue;
        }

        if arg == "--help" {
            return Ok(CliOutcome::Help);
        }
        if arg == "--version" {
            return Ok(CliOutcome::Version);
        }

        if let Some((name, attached_value)) = split_long_option(arg) {
            match name {
                "--output" => {
                    let value = attached_value
                        .map(str::to_owned)
                        .or_else(|| next_option_value(args, &mut index))
                        .ok_or(CliError::MissingValue("--output <OUTPUT_FILE_PATH>"))?;
                    seen.check_duplicate(ArgId::Output)?;
                    seen.check_conflict(ArgId::Output, &[ArgId::GenerateCompletions, ArgId::Test, ArgId::TestFile])?;
                    seen.mark(ArgId::Output);
                    options.output = Some(value);
                }
                "--no-color" => {
                    seen.check_duplicate(ArgId::NoColor)?;
                    seen.mark(ArgId::NoColor);
                    options.no_color = true;
                }
                "--repl" => {
                    seen.check_duplicate(ArgId::Repl)?;
                    seen.check_conflict(ArgId::Repl, &[ArgId::GenerateCompletions, ArgId::Test, ArgId::TestFile])?;
                    seen.mark(ArgId::Repl);
                    options.repl = true;
                }
                "--generate-completions" => {
                    let value = attached_value
                        .map(str::to_owned)
                        .or_else(|| next_option_value(args, &mut index))
                        .ok_or(CliError::MissingValue("--generate-completions <completions>"))?;
                    seen.check_duplicate(ArgId::GenerateCompletions)?;
                    seen.check_conflict(
                        ArgId::GenerateCompletions,
                        &[ArgId::Output, ArgId::Repl, ArgId::Test, ArgId::TestFile, ArgId::Input],
                    )?;
                    seen.mark(ArgId::GenerateCompletions);
                    options.generate_completions = Some(value);
                }
                "--test" => {
                    let value = attached_value
                        .map(str::to_owned)
                        .or_else(|| next_option_value(args, &mut index))
                        .ok_or(CliError::MissingValue("--test <test>"))?;
                    seen.check_duplicate(ArgId::Test)?;
                    seen.check_conflict(ArgId::Test, &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::TestFile])?;
                    seen.mark(ArgId::Test);
                    options.test = Some(value);
                }
                "--test-file" => {
                    let value = attached_value
                        .map(str::to_owned)
                        .or_else(|| next_option_value(args, &mut index))
                        .ok_or(CliError::MissingValue("--test-file <test-file>"))?;
                    seen.check_duplicate(ArgId::TestFile)?;
                    seen.check_conflict(ArgId::TestFile, &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::Test])?;
                    seen.mark(ArgId::TestFile);
                    options.test_file = Some(value);
                }
                _ => {
                    return Err(CliError::UnexpectedArgument {
                        arg: arg.clone(),
                        tip: true,
                    })
                }
            }

            index += 1;
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            let mut chars = arg[1..].char_indices().peekable();
            let mut consumed_next = false;

            while let Some((offset, ch)) = chars.next() {
                match ch {
                    'h' => return Ok(CliOutcome::Help),
                    'V' => return Ok(CliOutcome::Version),
                    'n' => {
                        seen.check_duplicate(ArgId::NoColor)?;
                        seen.mark(ArgId::NoColor);
                        options.no_color = true;
                    }
                    'r' => {
                        seen.check_duplicate(ArgId::Repl)?;
                        seen.check_conflict(ArgId::Repl, &[ArgId::GenerateCompletions, ArgId::Test, ArgId::TestFile])?;
                        seen.mark(ArgId::Repl);
                        options.repl = true;
                    }
                    'o' | 't' | 'f' => {
                        let value = if let Some((next_offset, _)) = chars.peek() {
                            arg[1 + *next_offset..].to_string()
                        } else {
                            consumed_next = true;
                            next_option_value(args, &mut index).ok_or_else(|| {
                                CliError::MissingValue(match ch {
                                    'o' => "--output <OUTPUT_FILE_PATH>",
                                    't' => "--test <test>",
                                    'f' => "--test-file <test-file>",
                                    _ => unreachable!(),
                                })
                            })?
                        };

                        match ch {
                            'o' => {
                                seen.check_duplicate(ArgId::Output)?;
                                seen.check_conflict(
                                    ArgId::Output,
                                    &[ArgId::GenerateCompletions, ArgId::Test, ArgId::TestFile],
                                )?;
                                seen.mark(ArgId::Output);
                                options.output = Some(value);
                            }
                            't' => {
                                seen.check_duplicate(ArgId::Test)?;
                                seen.check_conflict(
                                    ArgId::Test,
                                    &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::TestFile],
                                )?;
                                seen.mark(ArgId::Test);
                                options.test = Some(value);
                            }
                            'f' => {
                                seen.check_duplicate(ArgId::TestFile)?;
                                seen.check_conflict(
                                    ArgId::TestFile,
                                    &[ArgId::Output, ArgId::Repl, ArgId::GenerateCompletions, ArgId::Test],
                                )?;
                                seen.mark(ArgId::TestFile);
                                options.test_file = Some(value);
                            }
                            _ => {}
                        }

                        break;
                    }
                    _ => {
                        return Err(CliError::UnexpectedArgument {
                            arg: format!("-{ch}"),
                            tip: false,
                        })
                    }
                }

                let _ = offset;
            }

            index += if consumed_next { 2 } else { 1 };
            continue;
        }

        set_input_path(&mut options, &mut seen, arg.clone())?;
        index += 1;
    }

    Ok(CliOutcome::Run(options))
}

fn set_input_path(options: &mut CliOptions, seen: &mut SeenArgs, value: String) -> Result<(), CliError> {
    if options.input_file_path.is_some() {
        return Err(CliError::UnexpectedArgument {
            arg: value,
            tip: false,
        });
    }

    seen.check_conflict(ArgId::Input, &[ArgId::GenerateCompletions])?;
    seen.mark(ArgId::Input);
    options.input_file_path = Some(value);
    Ok(())
}

fn split_long_option(arg: &str) -> Option<(&str, Option<&str>)> {
    if !arg.starts_with("--") || arg == "--" {
        return None;
    }

    if let Some((name, value)) = arg.split_once('=') {
        Some((name, Some(value)))
    } else {
        Some((arg, None))
    }
}

fn next_option_value(args: &[String], index: &mut usize) -> Option<String> {
    let next = args.get(*index + 1)?;
    if next != "-" && next.starts_with('-') {
        return None;
    }
    Some(next.clone())
}

